import { createBackendModule } from '@backstage/backend-plugin-api';
import { scaffolderActionsExtensionPoint } from '@backstage/plugin-scaffolder-node/alpha';
import { createJiraProjectAction } from './actions/jira';

export const scaffolderModuleAcme = createBackendModule({
  pluginId: 'scaffolder',
  moduleId: 'acme-actions',
  register(env) {
    env.registerInit({
      deps: { scaffolder: scaffolderActionsExtensionPoint },
      async init({ scaffolder }) {
        scaffolder.addActions(createJiraProjectAction());
      },
    });
  },
});

// packages/backend/src/index.ts
backend.add(import('@backstage/plugin-scaffolder-backend'));
backend.add(import('@internal/plugin-scaffolder-backend-module-acme'));

import { createCatalogConditionalDecision, catalogConditions } from '@backstage/plugin-catalog-backend/alpha';
import { isResourcePermission } from '@backstage/plugin-permission-common';

async handle(request, user) {
  if (user?.principal && isServicePrincipal(user.principal)) return { result: AuthorizeResult.ALLOW };
  if (isResourcePermission(request.permission, 'catalog-entity')) {
    return createCatalogConditionalDecision(
      request.permission,
      catalogConditions.isEntityOwner({ claims: user?.info.ownershipEntityRefs ?? [] }),
    );
  }
  return { result: AuthorizeResult.DENY };
}
